namespace brunsli {

typedef enum {
  BRUNSLI_OK = 0,

  // Used if the input is not representable in the compressed brunsli format,
  // either because it is not a valid JPEG file or if some other limitation
  // is exceeded (e.g. absolute value of coefficients or number of Huffman
  // codes).
  BRUNSLI_NON_REPRESENTABLE,

  BRUNSLI_MEMORY_ERROR,
  BRUNSLI_INVALID_PARAM,

  BRUNSLI_COMPRESSION_ERROR,

  BRUNSLI_INVALID_BRN,
  BRUNSLI_DECOMPRESSION_ERROR,

  BRUNSLI_NOT_ENOUGH_DATA,
} BrunsliStatus;

}  // namespace brunsli

struct JPEGQuantTable {
  std::array<int32_t, kDCTBlockSize> values;
  int precision = 0;
  int index = 0;
  bool is_last = true;
};

struct JPEGHuffmanCode {
  std::array<int, kJpegHuffmanMaxBitLength + 1> counts = {};
  std::array<int, kJpegHuffmanAlphabetSize + 1> values = {};
  int slot_id = 0;
  bool is_last = true;
};

struct JPEGComponentScanInfo {
  uint8_t comp_idx;
  int dc_tbl_idx;
  int ac_tbl_idx;
};

struct JPEGScanInfo {
  int Ss;
  int Se;
  int Ah;
  int Al;
  size_t num_components = 0;
  std::array<JPEGComponentScanInfo, 4> components;
  std::vector<int> reset_points;
  typedef struct {
    int block_idx;
    int num_extra_zero_runs;
  } ExtraZeroRunInfo;
  std::vector<ExtraZeroRunInfo> extra_zero_runs;
};

struct JPEGComponent {
  JPEGComponent() : id(0),
                    h_samp_factor(1),
                    v_samp_factor(1),
                    quant_idx(0),
                    width_in_blocks(0),
                    height_in_blocks(0) {}

  int id;
  int h_samp_factor;
  int v_samp_factor;
  uint8_t quant_idx;
  uint32_t width_in_blocks;
  uint32_t height_in_blocks;
  uint32_t num_blocks;
  std::vector<coeff_t> coeffs;
};

struct JPEGData {
  JPEGData() : width(0),
               height(0),
               version(2),
               max_h_samp_factor(1),
               max_v_samp_factor(1),
               MCU_rows(0),
               MCU_cols(0),
               restart_interval(0),
               original_jpg(NULL),
               original_jpg_size(0),
               error(JPEGReadError::OK),
               has_zero_padding_bit(false) {}

  int width;
  int height;
  int version;
  int max_h_samp_factor;
  int max_v_samp_factor;
  int MCU_rows;
  int MCU_cols;
  int restart_interval;
  std::vector<std::vector<uint8_t>> app_data;
  std::vector<std::vector<uint8_t>> com_data;
  std::vector<JPEGQuantTable> quant;
  std::vector<JPEGHuffmanCode> huffman_code;
  std::vector<JPEGComponent> components;
  std::vector<JPEGScanInfo> scan_info;
  std::vector<uint8_t> marker_order;
  std::vector<std::vector<uint8_t>> inter_marker_data;
  std::vector<uint8_t> tail_data;
  const uint8_t* original_jpg;
  size_t original_jpg_size;
  JPEGReadError error;
  bool has_zero_padding_bit;
  std::vector<int> padding_bits;
};

struct JPEGOutput {
  JPEGOutput(JPEGOutputHook cb, void* data) : cb(cb), data(data) {}
  bool Write(const uint8_t* buf, size_t len) const {
    if (len == 0) return true;
    size_t bytes_written = cb(data, buf, len);
    return (bytes_written == len);
  }

 private:
  JPEGOutputHook cb;
  void* data;
};

class BrunsliDecoder {
 public:
  BrunsliDecoder();
  ~BrunsliDecoder();

  enum Status {
    NEEDS_MORE_INPUT,
    NEEDS_MORE_OUTPUT,
    ERROR,
    DONE,
  };

  Status Decode(size_t* available_in, const uint8_t** next_in,
                size_t* available_out, uint8_t** next_out);

 private:
  std::unique_ptr<JPEGData> jpg_;
  std::unique_ptr<::brunsli::internal::dec::State> state_;
};

enum Status {
    NEEDS_MORE_INPUT,
    NEEDS_MORE_OUTPUT,
    ERROR,
    DONE,
  };

