// Configure jpg to exercise 4:2:0 detection and negative cases.
// We choose among three scenarios to cover both true and false paths.
unsigned int scenario = *FUZZ_PARAM(unsigned int) % 3;

// Ensure sane dimensions to satisfy the "valid initialized" expectation.
// Keep them small for performance.
int w = (int)(*FUZZ_PARAM(unsigned int) % 1024u) + 1;  // [1,1024]
int h = (int)(*FUZZ_PARAM(unsigned int) % 1024u) + 1;  // [1,1024]
jpg->width = w;
jpg->height = h;

if (scenario == 0) {
  // Force an exact 4:2:0 layout:
  // components.size()==3, max_h=max_v=2,
  // Y: 2x2, Cb:1x1, Cr:1x1
  jpg->components.clear();
  jpg->components.resize(3);
  jpg->max_h_samp_factor = 2;
  jpg->max_v_samp_factor = 2;
  jpg->components[0].h_samp_factor = 2;
  jpg->components[0].v_samp_factor = 2;
  jpg->components[1].h_samp_factor = 1;
  jpg->components[1].v_samp_factor = 1;
  jpg->components[2].h_samp_factor = 1;
  jpg->components[2].v_samp_factor = 1;

  bool is420 = brunsli::JPEGDataIs420(*jpg);
  // Property: when we explicitly set 4:2:0, the function must return true.
  FUZZ_ASSERT(is420, "JPEGDataIs420 should return true for explicit 4:2:0 layout");
} else if (scenario == 1) {
  // Force an exact 4:4:4 layout (definitely not 4:2:0):
  jpg->components.clear();
  jpg->components.resize(3);
  jpg->max_h_samp_factor = 1;
  jpg->max_v_samp_factor = 1;
  for (int i = 0; i < 3; ++i) {
    jpg->components[i].h_samp_factor = 1;
    jpg->components[i].v_samp_factor = 1;
  }
  bool is420 = brunsli::JPEGDataIs420(*jpg);
  // Property: 4:4:4 must not be reported as 4:2:0.
  FUZZ_ASSERT(!is420, "JPEGDataIs420 should return false for 4:4:4 layout");
} else {
  // Force a configuration that cannot be 4:2:0 by changing component count.
  // This guarantees a false result regardless of sampling factors.
  jpg->components.clear();
  jpg->components.resize(2);  // not equal to 3
  jpg->max_h_samp_factor = (int)(*FUZZ_PARAM(unsigned int) % 4u) + 1; // [1..4]
  jpg->max_v_samp_factor = (int)(*FUZZ_PARAM(unsigned int) % 4u) + 1; // [1..4]
  for (size_t i = 0; i < jpg->components.size(); ++i) {
    jpg->components[i].h_samp_factor = (int)(*FUZZ_PARAM(unsigned int) % 4u) + 1;
    jpg->components[i].v_samp_factor = (int)(*FUZZ_PARAM(unsigned int) % 4u) + 1;
  }
  bool is420 = brunsli::JPEGDataIs420(*jpg);
  FUZZ_ASSERT(!is420, "JPEGDataIs420 should return false when components.size()!=3");
}

// Output: jpg is persistent and returned to the pool.
// Validation: The stub enforces exact-positive and exact-negative layouts and asserts
// correctness of brunsli::JPEGDataIs420 for those cases.

// Configure jpg to exercise 4:4:4 detection and negative cases.
unsigned int scenario = *FUZZ_PARAM(unsigned int) % 3;

// Ensure valid dimensions.
int w = (int)(*FUZZ_PARAM(unsigned int) % 1024u) + 1;
int h = (int)(*FUZZ_PARAM(unsigned int) % 1024u) + 1;
jpg->width = w;
jpg->height = h;

if (scenario == 0) {
  // Force exact 4:4:4: components==3, max_h=max_v=1, all comps 1x1.
  jpg->components.clear();
  jpg->components.resize(3);
  jpg->max_h_samp_factor = 1;
  jpg->max_v_samp_factor = 1;
  for (int i = 0; i < 3; ++i) {
    jpg->components[i].h_samp_factor = 1;
    jpg->components[i].v_samp_factor = 1;
  }
  bool is444 = brunsli::JPEGDataIs444(*jpg);
  FUZZ_ASSERT(is444, "JPEGDataIs444 should return true for explicit 4:4:4 layout");
} else if (scenario == 1) {
  // Force exact 4:2:0: definitely not 4:4:4.
  jpg->components.clear();
  jpg->components.resize(3);
  jpg->max_h_samp_factor = 2;
  jpg->max_v_samp_factor = 2;
  jpg->components[0].h_samp_factor = 2;
  jpg->components[0].v_samp_factor = 2;
  jpg->components[1].h_samp_factor = 1;
  jpg->components[1].v_samp_factor = 1;
  jpg->components[2].h_samp_factor = 1;
  jpg->components[2].v_samp_factor = 1;
  bool is444 = brunsli::JPEGDataIs444(*jpg);
  FUZZ_ASSERT(!is444, "JPEGDataIs444 should return false for 4:2:0 layout");
} else {
  // Force a configuration that cannot be 4:4:4 by changing component count.
  jpg->components.clear();
  jpg->components.resize(1); // not equal to 3
  jpg->max_h_samp_factor = (int)(*FUZZ_PARAM(unsigned int) % 4u) + 1;
  jpg->max_v_samp_factor = (int)(*FUZZ_PARAM(unsigned int) % 4u) + 1;
  jpg->components[0].h_samp_factor = (int)(*FUZZ_PARAM(unsigned int) % 4u) + 1;
  jpg->components[0].v_samp_factor = (int)(*FUZZ_PARAM(unsigned int) % 4u) + 1;
  bool is444 = brunsli::JPEGDataIs444(*jpg);
  FUZZ_ASSERT(!is444, "JPEGDataIs444 should return false when components.size()!=3");
}

// Output: jpg is persistent and returned to the pool.
// Validation: The stub deterministically creates true and false layouts and asserts
// the function's result accordingly.

// Exercise PaddingBitsLimit and assert monotonicity with respect to dimensions.
// Keep a stable sampling layout so only width/height change between calls.
unsigned int layout = *FUZZ_PARAM(unsigned int) & 1u; // 0: 4:2:0, 1: 4:4:4

jpg->components.clear();
jpg->components.resize(3);
if (layout == 0) {
  // 4:2:0
  jpg->max_h_samp_factor = 2;
  jpg->max_v_samp_factor = 2;
  jpg->components[0].h_samp_factor = 2; jpg->components[0].v_samp_factor = 2;
  jpg->components[1].h_samp_factor = 1; jpg->components[1].v_samp_factor = 1;
  jpg->components[2].h_samp_factor = 1; jpg->components[2].v_samp_factor = 1;
} else {
  // 4:4:4
  jpg->max_h_samp_factor = 1;
  jpg->max_v_samp_factor = 1;
  for (int i = 0; i < 3; ++i) {
    jpg->components[i].h_samp_factor = 1;
    jpg->components[i].v_samp_factor = 1;
  }
}

// Choose two increasing dimension pairs to test monotonicity.
uint32_t w1 = (uint32_t)(*FUZZ_PARAM(unsigned int) % 1024u) + 1; // [1,1024]
uint32_t h1 = (uint32_t)(*FUZZ_PARAM(unsigned int) % 1024u) + 1; // [1,1024]
uint32_t dw = (uint32_t)(*FUZZ_PARAM(unsigned int) % 1024u);
uint32_t dh = (uint32_t)(*FUZZ_PARAM(unsigned int) % 1024u);
uint32_t w2 = w1 + dw; // >= w1
uint32_t h2 = h1 + dh; // >= h1

// First call
jpg->width = (int)w1;
jpg->height = (int)h1;
uint64_t limit1 = brunsli::PaddingBitsLimit(*jpg);

// Second call with larger or equal dimensions
jpg->width = (int)w2;
jpg->height = (int)h2;
uint64_t limit2 = brunsli::PaddingBitsLimit(*jpg);

// Property: Increasing dimensions should not decrease the upper bound.
FUZZ_ASSERT(limit2 >= limit1, "PaddingBitsLimit must be monotonic in image dimensions");

// Output: jpg is persistent and returned to the pool.
// Validation: The stub pins a stable sampling layout and asserts monotonicity of
// PaddingBitsLimit as width/height increase.

// Generate an input buffer. FUZZ_PARAM_STR returns 1..4096 bytes; we may also
// test the len==0 path by occasionally setting len to 0 while keeping a valid pointer.
std::string in = FUZZ_PARAM_STR();
const uint8_t* data = reinterpret_cast<const uint8_t*>(in.data());
size_t len = in.size();

// Randomly decide to present an empty length to exercise the "no data" path.
unsigned mode_seed = *FUZZ_PARAM(unsigned int);
if ((mode_seed % 8) == 0) {
  // len==0 is allowed by the API (though it cannot succeed). Data remains non-null.
  len = 0;
}

// Constrain mode to valid JpegReadMode domain [0..2]. We avoid naming the enum values
// directly and rely on contiguous definitions starting at 0, per API description.
brunsli::JpegReadMode mode = static_cast<brunsli::JpegReadMode>(mode_seed % 3);

// Enforce required preconditions:
// - data must point to at least len bytes; satisfied by string storage lifetime.
// - jpg must be non-null (provided by fuzzer runtime as an input object).
if (!jpg) { FUZZ_BAIL(); }
if (len > 0 && data == nullptr) { FUZZ_BAIL(); }

// Call the target function.
bool ok = brunsli::ReadJpeg(data, len, mode, jpg);

// Track outcome and metadata for downstream stubs (if any).
FUZZ_SET_ATTR_INT(jpg, "read_mode", static_cast<int>(mode));
FUZZ_SET_ATTR_INT(jpg, "read_success", ok ? 1 : 0);
// Store a truncated size hint (attribute API supports int only).
FUZZ_SET_ATTR_INT(jpg, "input_size_hint", (int)(len & 0x7FFFFFFF));

// Requirement: jpg must be initialized. We trust the fuzzer runtime to provide a non-null JPEGData*.
// We simply query the worst-case encoded size and stash it as an attribute for potential downstream use.
size_t max_size = brunsli::GetMaximumBrunsliEncodedSize(*jpg);
// Record a truncated hint for downstream stubs (best-effort; attribute API holds int).
if (max_size > static_cast<size_t>(INT32_MAX)) {
  FUZZ_SET_ATTR_INT(jpg, "brunsli.max_size", INT32_MAX);
} else {
  FUZZ_SET_ATTR_INT(jpg, "brunsli.max_size", static_cast<int>(max_size));
}
// Validation: API should return an upper bound; no hard properties to assert here beyond interface adherence.
// Validation summary: The stub calls the function with a valid reference and preserves jpg for the pool.

// Requirements enforcement:
// - jpg must be valid: provided by runtime as non-null.
// - len must be non-null and on entry hold capacity of data; we set it accordingly.
// - data must be a writable buffer of at least *len bytes; we allocate std::string for storage.

// Use the sizing helper to choose a capacity. Cap the buffer to keep fuzzer performance reasonable.
size_t estimate = brunsli::GetMaximumBrunsliEncodedSize(*jpg);
size_t cap = estimate == 0 ? 1 : estimate;
if (cap > 2048) cap = 2048;  // fuzzer performance guard
std::string out(cap, '\0');
size_t len = cap;

bool ok = brunsli::BrunsliEncodeJpeg(*jpg, reinterpret_cast<uint8_t*>(&out[0]), &len);
// Postconditions:
// - On success, len is the number of bytes written and must be <= capacity.
if (ok) {
  FUZZ_ASSERT(len <= cap, "BrunsliEncodeJpeg reported more bytes than buffer capacity");
}
// Record last encode size (best-effort diagnostic for other stubs).
FUZZ_SET_ATTR_INT(jpg, "brunsli.last_encode_len", (len > static_cast<size_t>(INT32_MAX)) ? INT32_MAX : static_cast<int>(len));
// Validation summary: Provides non-null buffer/len, respects capacity, asserts basic success property, and returns jpg to pool.

// Requirements: jpg_size is the size in bytes of the input JPEG data; we fuzz it within a sane bound.
size_t jpg_size = static_cast<size_t>(*FUZZ_PARAM(unsigned int)) % 4097; // 0..4096
size_t bypass_size = brunsli::GetBrunsliBypassSize(jpg_size);
(void)bypass_size; // Used for coverage; no strict properties to assert here.
// Validation summary: Calls with a valid size_t argument and consumes return value; no persistent objects involved.

// Requirements enforcement:
// - jpg_data points to the input JPEG stream when jpg_data_len > 0. FUZZ_PARAM_STR provides non-empty data.
// - len must be non-null and on entry contain capacity of data; we set it and provide a writable buffer.
// - Callers should size capacity >= GetBrunsliBypassSize(jpg_data_len); we sometimes under/over-provision to explore both paths.

std::string in = FUZZ_PARAM_STR();
const uint8_t* jpg_data = reinterpret_cast<const uint8_t*>(in.data());
size_t jpg_data_len = in.size();

// Choose an output capacity based on bypass size and additional fuzzing, bounded for performance.
size_t ideal = brunsli::GetBrunsliBypassSize(jpg_data_len);
unsigned int fuzz = *FUZZ_PARAM(unsigned int);
// Mix: sometimes smaller than ideal, sometimes equal/greater.
size_t desired = ideal;
if ((fuzz & 1) == 0) {
  // Undersize by up to half, but at least 1
  size_t shrink = (ideal > 0) ? (ideal / 2) : 0;
  desired = (ideal > shrink) ? (ideal - shrink) : 1;
} else {
  // Oversize by up to +25%
  desired = ideal + (ideal / 4);
}
if (desired == 0) desired = 1;
if (desired > 2048) desired = 2048; // performance guard

std::string out(desired, '\0');
size_t len = desired;

bool ok = brunsli::BrunsliEncodeJpegBypass(jpg_data, jpg_data_len,
    reinterpret_cast<uint8_t*>(&out[0]), &len);
if (ok) {
  FUZZ_ASSERT(len <= desired, "BrunsliEncodeJpegBypass wrote more than capacity");
}
// Validation summary: Provides a valid input span and writable output buffer with capacity tracking; asserts size-on-success property.

// One-shot Brunsli encoder harness: generate an input buffer, and a callback sink.
// Enforce constraints:
//  - insize equals the actual input size
//  - in points to a valid readable region for duration of the call
//  - outfun is a valid function pointer; it returns size on success or a short
//    write to signal failure; we use a fuzzed flag to exercise both paths.
{
  // Create a random input buffer to serve as a complete JPEG bitstream.
  // FUZZ_PARAM_STR() returns a string of size in [1, 4096].
  std::string jpeg = FUZZ_PARAM_STR();
  size_t insize = jpeg.size();
  // Ensure non-null pointer when insize > 0 by referencing string storage.
  const unsigned char* in = reinterpret_cast<const unsigned char*>(jpeg.data());

  // Small output buffer context carried via outdata (opaque to the API).
  struct OutBuf {
    std::vector<uint8_t> data;
    size_t max;
    int should_error; // when non-zero, simulate a short write
    OutBuf(): max(2048), should_error(0) {}
  } out_ctx;

  // Randomly decide whether the sink should simulate an error (short write) to
  // cover the callback-error path. Roughly 50% chance.
  out_ctx.should_error = (int)(*FUZZ_PARAM(unsigned int) & 1u);

  // Non-capturing lambda decays to function pointer with the required signature.
  auto outfun = +[](void* outdata, const unsigned char* buf, size_t size) -> size_t {
    OutBuf* ob = static_cast<OutBuf*>(outdata);
    if (!ob) return 0; // if context missing, signal error to the encoder

    // Copy up to 'max' bytes across all calls to avoid excessive allocations.
    size_t space = (ob->data.size() < ob->max) ? (ob->max - ob->data.size()) : 0;
    size_t to_copy = (size < space) ? size : space;
    if (to_copy > 0 && buf != nullptr) {
      ob->data.insert(ob->data.end(), buf, buf + to_copy);
    }

    // If we simulate an error, return a short count (but never negative / wrap).
    if (ob->should_error) {
      if (size == 0) return 0; // zero-length writes are trivially successful
      // Return size-1 to indicate failure per API contract.
      return size - 1;
    }
    // Normal success case: report full consumption.
    return size;
  };

  void* outdata = &out_ctx; // opaque sink context passed through to the callback

  // Invoke the target API. Returns 1 on success, 0 on error. We do not assert
  // success since the input may be invalid JPEG or the sink may force failure.
  int ok = EncodeBrunsli(insize, in, outdata, outfun);
  (void)ok; // allow both success and failure for coverage

  // Validation summary: insize matches the buffer size; 'in' is valid for call
  // lifetime; outfun is a valid function pointer and sometimes signals error to
  // exercise both encoder success and failure paths.
}

// Construct a new JPEGData with coherent, bounded fields suitable for downstream APIs.
brunsli::JPEGData* jpg = new brunsli::JPEGData();

// Dimensions: keep small and positive for performance and validity.
jpg->width  = (int)(*FUZZ_PARAM(unsigned int) % 1024u) + 1;   // [1..1024]
jpg->height = (int)(*FUZZ_PARAM(unsigned int) % 1024u) + 1;   // [1..1024]

// Choose number of components: typical JPEGs have 1 (grayscale) or 3 (YCbCr/RGB).
size_t num_components = (size_t)(*FUZZ_PARAM(unsigned int) % 3u) + 1; // [1..3]
jpg->components.clear();
jpg->components.resize(num_components);

// Sampling factors: choose 1..2; compute maxima for frame.
int max_h = 1;
int max_v = 1;
for (size_t i = 0; i < num_components; ++i) {
  brunsli::JPEGComponent& c = jpg->components[i];
  c.id = (int)i + 1; // typical IDs 1..num_components
  c.h_samp_factor = (int)(*FUZZ_PARAM(unsigned int) % 2u) + 1; // 1..2
  c.v_samp_factor = (int)(*FUZZ_PARAM(unsigned int) % 2u) + 1; // 1..2
  if (c.h_samp_factor > max_h) max_h = c.h_samp_factor;
  if (c.v_samp_factor > max_v) max_v = c.v_samp_factor;
}
jpg->max_h_samp_factor = max_h;
jpg->max_v_samp_factor = max_v;

// Quantization tables: 1..4 tables, precision 0 or 1, indices 0..3.
size_t num_quant = (size_t)(*FUZZ_PARAM(unsigned int) % 4u) + 1; // [1..4]
jpg->quant.clear();
jpg->quant.resize(num_quant);
for (size_t qi = 0; qi < num_quant; ++qi) {
  brunsli::JPEGQuantTable& qt = jpg->quant[qi];
  qt.precision = (int)(*FUZZ_PARAM(unsigned int) & 1u); // 0 or 1
  qt.index = (int)qi; // 0..3 unique
  qt.is_last = (qi + 1 == num_quant);
  // Fill with a simple bounded pattern to avoid extreme values.
  for (size_t k = 0; k < qt.values.size(); ++k) {
    // values in [1..255] for 8-bit precision; if precision==1 (16-bit), values may exceed 255.
    int32_t base = (int32_t)(*FUZZ_PARAM(unsigned int) % 255u) + 1;
    qt.values[k] = (qt.precision == 0) ? base : (base * 2);
  }
}

// Huffman tables: create a few minimal tables with valid structure shapes.
size_t num_huff = (size_t)(*FUZZ_PARAM(unsigned int) % 6u) + 1; // [1..6]
jpg->huffman_code.clear();
jpg->huffman_code.resize(num_huff);
for (size_t hi = 0; hi < num_huff; ++hi) {
  brunsli::JPEGHuffmanCode& hc = jpg->huffman_code[hi];
  // Minimal valid tree: one symbol of length 1 bit.
  for (size_t i = 0; i < hc.counts.size(); ++i) hc.counts[i] = 0;
  hc.counts[1] = 1; // one code of length 1
  for (size_t i = 0; i < hc.values.size(); ++i) hc.values[i] = 0;
  hc.values[0] = (int)(*FUZZ_PARAM(unsigned int) % 256u);
  // Slot id: DC(0..3) or AC(0x10..0x13)
  int is_ac = (int)(*FUZZ_PARAM(unsigned int) & 1u);
  int tbl = (int)(*FUZZ_PARAM(unsigned int) % 4u);
  hc.slot_id = is_ac ? (0x10 + tbl) : tbl;
  hc.is_last = (hi + 1 == num_huff);
}

// Components: set quantization indices and block geometry with bounded sizes.
for (size_t i = 0; i < num_components; ++i) {
  brunsli::JPEGComponent& c = jpg->components[i];
  c.quant_idx = (uint8_t)((num_quant == 0) ? 0 : (i % num_quant));
  // Keep blocks small to limit memory: up to 4x4 blocks per component.
  c.width_in_blocks  = (uint32_t)((*FUZZ_PARAM(unsigned int) % 4u) + 1);  // [1..4]
  c.height_in_blocks = (uint32_t)((*FUZZ_PARAM(unsigned int) % 4u) + 1);  // [1..4]
  c.num_blocks = c.width_in_blocks * c.height_in_blocks;
  // coeffs size = blocks * 64 DCT coefficients, bounded to <= 16*64 = 1024 entries.
  size_t coeff_count = (size_t)c.num_blocks * 64u;
  c.coeffs.clear();
  c.coeffs.resize(coeff_count);
  // Fill with small values. Note: FUZZ_PARAM in a loop yields the same value; that's OK here.
  int16_t val = (int16_t)((int)(*FUZZ_PARAM(int)) & 0x7F); // keep small
  for (size_t k = 0; k < coeff_count; ++k) c.coeffs[k] = val;
}

